<script setup lang="ts">
import {onHide as onPageHide} from "@dcloudio/uni-app"
import {abandonLogin as cancelPageLogin} from "../../features/auth"
onPageHide(cancelPageLogin)

import LoginSheet from "../../components/LoginSheet.vue"

import { ref } from 'vue';import { onShow } from '@dcloudio/uni-app';import { request,downloadFile,navigate,token,type Row } from '../../api/platform'
const packages=ref<Row[]>([]),exams=ref<Row[]>([]),artifacts=ref<Row[]>([]),selected=ref<Row|null>(null),kind=ref(''),error=ref('')
async function open(type:string,id:string){try{kind.value=type;selected.value=await request('GET','/api/v1/resources/'+type+'/'+id)}catch(e){error.value=(e as Error).message}}
async function download(id:string){if(!token()){navigate('login');return}try{await downloadFile(id)}catch(e){error.value=(e as Error).message}}
onShow(async()=>{try{[packages.value,exams.value,artifacts.value]=await Promise.all([request('GET','/api/v1/resources/packages'),request('GET','/api/v1/resources/exams'),request('GET','/api/v1/resources/artifacts')])}catch(e){error.value=(e as Error).message}})
</script>
<template><view class="page"><view class="hero"><text class="title">学习资料与工具</text><text class="subtitle">科目资料、考试安排和插件发布版本。</text></view><text class="error">{{ error }}</text><text class="section-title">考试日程</text><view v-for="exam in exams" :key="exam.id" class="card"><text class="card-title">{{ exam.subjectName }}</text><text class="muted">{{ exam.startsAt }} · {{ exam.displayTimezone }}</text><text class="badge">{{ exam.secondsRemaining>0?'距离考试 '+Math.ceil(exam.secondsRemaining/86400)+' 天':'已到考试时间' }}</text><text class="muted small">来源 {{ exam.sourceReference }}</text></view><view v-if="!exams.length" class="empty">暂无已发布考试安排</view><text class="section-title">资料包</text><view v-for="r in packages" :key="r.id" class="card" @click="open('packages',r.id)"><text class="card-title">{{ r.title }}</text><text class="muted">{{ r.subjectName }} · {{ r.resourceType }}</text><text class="click-hint">查看文件与下载 ›</text></view><view v-if="!packages.length" class="empty">暂无已发布资料包</view><text class="section-title">插件工具</text><view v-for="a in artifacts" :key="a.id" class="card" @click="open('artifacts',a.id)"><text class="card-title">{{ a.name }}</text><text class="muted">{{ a.platform }}</text><text class="click-hint">查看版本与插件教程 ›</text></view><view v-if="!artifacts.length" class="empty">暂无已发布插件，发布后可在这里下载和查看教程。</view><view v-if="selected" class="card"><view class="row"><text class="card-title">{{ selected.title||selected.name }}</text><button role="button" class="quiet" @click="selected=null">收起</button></view><template v-if="kind==='packages'"><view v-for="f in selected.files" :key="f.fileId+'-'+f.versionNo" class="list-item"><text>{{ f.displayName }}</text><text class="muted small">SHA256 {{ f.sha256 }}</text><button role="button" class="secondary" @click="download(f.fileId)">下载文件</button></view><button role="button" v-if="selected.articleId" class="quiet" @click="navigate('article','?id='+selected.articleId)">使用教程</button></template><template v-else><view v-for="v in selected.versions" :key="v.id" class="list-item"><text class="card-title">{{ v.versionName }}</text><text>{{ v.releaseNotes }}</text><text class="muted small">SHA256 {{ v.sha256 }}</text><button role="button" class="secondary" @click="download(v.fileId)">下载发布包</button></view><button role="button" v-if="selected.guideArticleId" class="quiet" @click="navigate('article','?id='+selected.guideArticleId)">插件教程</button></template></view><LoginSheet/></view></template>
